const CAT_CHAIRMAN = '\u4e3b\u59d4';
const CAT_REP = '\u5168\u4ee3';
const CAT_CITY = '\u5e02\u4ee3';
const FIELD_NAME = '\u59d3\u540d';
const FIELD_CATEGORY = '\u985e\u5225';
const FIELD_VOTED = '\u5df2\u6295\u7968';
const FIELD_CHAIRMAN_VOTE = '\u6295\u7d66\u4e3b\u59d4';
const FIELD_REP_VOTE = '\u6295\u7d66\u5168\u4ee3';
const FIELD_CITY_VOTE = '\u6295\u7d66\u5e02\u4ee3';
const CATEGORY_BY_NAME = {
  '\u8a31\u6728\u6842': CAT_CHAIRMAN,
  '\u9673\u6021\u6f54': CAT_REP,
  '\u90b1\u67cf\u745e': CAT_REP,
  '\u9ec3\u7f8e\u60e0': CAT_CITY,
  '\u8cf4\u79c0\u5982': CAT_CITY,
  '\u6797\u5fd7\u9d3b': CAT_CITY,
  '\u738b\u4fca\u5091': CAT_CITY,
  '\u9673\u4f69\u541b': CAT_CITY
};
function deepValues(value, out = []) {
  if (value == null) return out;
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    out.push(String(value));
    return out;
  }
  if (Array.isArray(value)) {
    value.forEach((entry) => deepValues(entry, out));
    return out;
  }
  if (typeof value === 'object') Object.values(value).forEach((entry) => deepValues(entry, out));
  return out;
}
function compact(value) {
  return String(value || '').replace(/\s+/g, '').trim();
}
function text(value) {
  return deepValues(value).join('');
}
function prop(json, names, type) {
  const wanted = (Array.isArray(names) ? names : [names]).map(compact);
  const props = json.properties || {};
  for (const name of names) {
    if (json[name] != null) return json[name];
    if (json['property_' + name] != null) return json['property_' + name];
    if (props[name] != null) return props[name];
  }
  for (const [key, value] of Object.entries(props)) {
    if (wanted.includes(compact(key))) return value;
  }
  for (const [key, value] of Object.entries(json)) {
    const normalized = compact(key).replace(/^property_/, '');
    if (wanted.includes(normalized)) return value;
  }
  if (type) return Object.values(props).find((value) => value?.type === type);
  return undefined;
}
function propText(json, names, type) {
  return text(prop(json, names, type)).trim();
}
function titleText(json) {
  return propText(json, [FIELD_NAME, 'name', 'Name'], 'title') || String(json.name || '').trim();
}
function categoryText(json, name) {
  const explicit = propText(json, [FIELD_CATEGORY, 'category', 'Category'], 'select');
  if ([CAT_CHAIRMAN, CAT_REP, CAT_CITY].includes(explicit)) return explicit;
  const values = deepValues(json).map((value) => String(value).trim()).filter(Boolean);
  if (values.includes(CAT_CHAIRMAN)) return CAT_CHAIRMAN;
  if (values.includes(CAT_REP)) return CAT_REP;
  if (values.includes(CAT_CITY)) return CAT_CITY;
  return CATEGORY_BY_NAME[name] || '';
}
function isChecked(json) {
  const value = prop(json, [FIELD_VOTED], 'checkbox');
  if (typeof value === 'boolean') return value;
  if (value?.checkbox != null) return Boolean(value.checkbox);
  return false;
}
const candidates = $('Get Vote Candidates').all().map((item) => {
  const name = titleText(item.json);
  return { name, category: categoryText(item.json, name), votes: 0 };
}).filter((item) => item.name);
const byName = new Map(candidates.map((item) => [compact(item.name), item]));
const records = $('Get Vote Records').all();
for (const record of records) {
  const selectedNames = [
    propText(record.json, [FIELD_CHAIRMAN_VOTE]),
    propText(record.json, [FIELD_REP_VOTE]),
    propText(record.json, [FIELD_CITY_VOTE])
  ].map(compact).filter(Boolean);
  const values = selectedNames.length ? selectedNames : deepValues(record.json).map(compact).filter(Boolean);
  for (const [name, candidate] of byName.entries()) {
    if (values.includes(name)) candidate.votes += 1;
  }
}
const voters = $('Get Vote Voters').all();
return [{ json: {
  success: true,
  candidates,
  totalVoters: voters.length,
  votedCount: voters.filter((item) => isChecked(item.json)).length,
  recordCount: records.length
} }];
